        else if ( gem.constant().hasValue() && gem.defaultValue().hasValue() ) {
        else if ( gem.constant().hasValue() && gem.defaultValue().hasValue() ) {
            message = Message.PROPERTYMAPPING_CONSTANT_AND_DEFAULT_VALUE_BOTH_DEFINED;
